typescript.text:
Дана следующая discriminated union для уведомлений:

interface Email { type: 'email'; email: string; }
interface SMS { type: 'sms'; phone: string; }
interface Push { type: 'push'; deviceId: string; }

type Notification = Email | SMS | Push;

Как реализовать функцию handleNotification с exhaustive проверкой типа notification?

options:
function handleNotification(notification: Notification) {
  switch(notification.type) {
    case 'email': sendEmail(notification.email); break;
    case 'sms': sendSMS(notification.phone); break;
  }
}

function handleNotification(notification: Notification) {
  switch(notification.type) {
    case 'email': sendEmail(notification.email); break;
    case 'sms': sendSMS(notification.phone); break;
    case 'push': sendPush(notification.deviceId); break;
    default: const _exhaustiveCheck: never = notification;
  }
}

function handleNotification(notification: Notification) {
  const { type } = notification;
  if(type === 'email') sendEmail(notification.email);
  if(type === 'sms') sendSMS(notification.phone);
}

function handleNotification(notification: Notification) {
  if(notification.type === 'email') sendEmail(notification.email);
  else if(notification.type === 'sms') sendSMS(notification.phone);
  else if(notification.type === 'push') sendPush(notification.deviceId);
}

